  std::size_t environment_size = 0;
  if (_dupenv_s(&environment, &environment_size, "EP_AUDITOR_SAVE_DIRECTORY") !=
      0)
    return 2;
  if (!environment && _dupenv_s(&environment, &environment_size,
                                "EP_AUDITOR_CAUSAL_DIRECTORY") != 0)
    return 2;
